mapper.select:
select count(*)
  from cms_content c
 where c.site_id = #{siteId}
   and c.type_code = #{typeCode}
   and c.deleted = 0

   and c.id <> #{excludeId}

choose.otherwise:
and exists (select 1 from cms_content_category cc
             where cc.content_id = c.id
               and cc.deleted = 0
               and cc.category_id in

                   #{cid}
               )

choose.when:
and exists (select 1 from cms_content_index ix
             where ix.site_id = #{p.siteId}
               and ix.content_id = c.id
               and ix.deleted = 0
               and ix.field_code = #{w.fieldCode}
               and ix.str_value ilike '%' || #{w.first} || '%')

and exists (select 1 from cms_content_index ix
             where ix.site_id = #{p.siteId}
               and ix.content_id = c.id
               and ix.deleted = 0
               and ix.field_code = #{w.fieldCode}
               and ix.value_key in

                   #{v}
               )

and exists (select 1 from cms_content_index ix
             where ix.site_id = #{p.siteId}
               and ix.content_id = c.id
               and ix.deleted = 0
               and ix.field_code = #{w.fieldCode}
               and ix.value_key = #{w.first})

choose.otherwise:
and exists (select 1 from cms_content_index ix
             where ix.site_id = #{p.siteId}
               and ix.content_id = c.id
               and ix.deleted = 0
               and ix.field_code = #{w.fieldCode}
               and )

mapper.select:
select c.*
  from cms_content c
 where c.site_id = #{p.siteId}
   and c.deleted = 0

 order by 

    limit #{p.limit} offset #{p.offset}

with recursive tree as ( select c.id, 1 as lvl from cms_content c where c.site_id = #{p.siteId} and c.deleted = 0 and c.parent_id in
#{pid}
union all select c.id, t.lvl + 1 from cms_content c join tree t on c.parent_id = t.id where t.lvl < #{p.depth} and c.site_id = #{p.siteId} and c.deleted = 0
) select c.* from cms_content c join tree t on t.id = c.id order by c.sort asc, c.id asc

select c.parent_id as parentId, count(*) as count from cms_content c where c.site_id = #{p.siteId} and c.deleted = 0 and c.parent_id in
#{pid}
group by c.parent_id

select extract(year from date_trunc(#{mode}::text, c.publish_time))::int as year, extract(month from date_trunc(#{mode}::text, c.publish_time))::int as month, count(*) as count from cms_content c where c.site_id = #{p.siteId} and c.deleted = 0 and c.publish_time is not null
group by 1, 2 order by 1 desc, 2 desc
limit #{p.limit}

select case when ix.value_key = 'default'
            then coalesce(ix.str_value, ix.value_key)
            else ix.value_key end as value,
       count(*) as count
  from cms_content_index ix
  join cms_content c on c.id = ix.content_id
 where ix.site_id = #{p.siteId}
   and ix.deleted = 0
   and ix.field_code = #{fieldCode}
   and c.site_id = #{p.siteId}
   and c.deleted = 0


 group by 1
 order by count(*) desc, 1 asc

    limit #{limit}
